package com.eurobuddha.terminalide.ide;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit editor lint and validation failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-wallet-error-languages.py from localization/terminal-editor-messages.json. */
public final class EditorMessages {
    private EditorMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "@BLKNUM is unreliable on synced nodes — store a timeout in state and use @COINAGE instead.": return Language.msg(l10n_terminal_editor_blknum);
            case "NUMBER(SHA...) overflows on a 32-byte hash — truncate first: NUMBER(SUBSET(0 4 SHA3(...))).": return Language.msg(l10n_terminal_editor_hash_overflow);
            case "No RETURN statement — a script must RETURN TRUE to be spendable.": return Language.msg(l10n_terminal_editor_no_return);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("Variable\\ '((?s:.*))'\\ contains\\ an\\ underscore\\ —\\ underscored\\ names\\ silently\\ fail\\ on\\-chain\\.\\ Use\\ flat\\ names\\ \\(e\\.g\\.\\ '((?s:.*))'\\)\\."),
        java.util.regex.Pattern.compile("Script\\ is\\ (-?[0-9]+)\\ chars\\ —\\ over\\ the\\ \\~(-?[0-9]+)\\ char\\ limit\\ scripts\\ are\\ silently\\ rejected\\ on\\-chain\\.\\ Minify\\ variable\\ names\\ or\\ use\\ MAST\\."),
        java.util.regex.Pattern.compile("Script\\ is\\ (-?[0-9]+)\\ chars\\ —\\ approaching\\ the\\ \\~(-?[0-9]+)\\ char\\ on\\-chain\\ limit\\."),
        java.util.regex.Pattern.compile("(-?[0-9]+)\\ unclosed\\ ((?s:.*))\\ block\\(s\\)\\ —\\ missing\\ ((?s:.*))\\."),
        java.util.regex.Pattern.compile("(-?[0-9]+)\\ extra\\ ((?s:.*))\\(s\\)\\ without\\ a\\ matching\\ ((?s:.*))\\."),
        java.util.regex.Pattern.compile("((?s:.*))\\ is\\ not\\ valid\\ JSON:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("((?s:.*))\\ values\\ can't\\ contain\\ spaces\\ or\\ ';'\\ \\(they'd\\ break\\ the\\ node\\ command\\ line\\)\\.\\ Use\\ hex/number\\ values\\.")
    };
    private static final int[] RESOURCES={l10n_terminal_editor_underscore,l10n_terminal_editor_size_over,l10n_terminal_editor_size_near,l10n_terminal_editor_unclosed,l10n_terminal_editor_extra,l10n_terminal_editor_json,l10n_terminal_editor_unsafe};
    private static final boolean[][] DIAGNOSTIC={{false,false},{false,false},{false,false},{false,false,false},{false,false,false},{false,false},{false}};
}
